import { test } from "node:test";
import assert from "node:assert/strict";
import * as big from "../src/big.mjs";

test("every helper matches its specification", () => {
  for (let i = 1; i <= 40; i += 1) {
    const fn = big["op" + i];
    assert.equal(typeof fn, "function", "op" + i + " must be exported");
    if (i === 27) {
      // op27 is specified as the product of its arguments.
      assert.equal(fn(6, 7), 42, "op27(6,7)");
      assert.equal(fn(3, 3), 9, "op27(3,3)");
    } else {
      assert.equal(fn(2, 3), 2 + 3 * i, "op" + i + "(2,3)");
    }
  }
});
